// NewTaskRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewTaskRetrievalObserver(observer string) TaskRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Task, TaskRetrievalHooks](observer)
}

// RegisterTaskRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterTaskRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer TaskRetrievalObserver, construct func(foundation.Resolver) (func() TaskRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (TaskRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Task], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Task, TaskRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Task]{}, err
	}
	var allHooks []TaskRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Task]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Task]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Task]{}, err
	}
	return foundryquery.RetrievalHooks[Task]{Retrieved: func(ctx context.Context, executor database.Executor, item Task) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

// TaskAuditPolicy selects stored fields for auditing. Zero applies automatic sensitive-name redaction.
// Exclusion/redaction cannot hide the primary key while retaining it as the subject identity; that policy fails capture.
type TaskAuditPolicy struct {
	_ [0]*Task
	// ID controls the audit representation of stored tasks.id.
	ID record.Disclosure
	// ProjectID controls the audit representation of stored tasks.project_id.
	ProjectID record.Disclosure
	// Slug controls the audit representation of stored tasks.slug.
	Slug record.Disclosure
}

// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes TaskChanges) Audit(policy TaskAuditPolicy) (record.Model[Task, model.ID[Task]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Task, model.ID[Task]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Task, model.ID[Task]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Task, model.ID[Task]]{}, err
	}
	if err = record.Capture(builder, "id", codec.ID[Task](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Task, model.ID[Task]]{}, err
	}
	if err = record.Capture(builder, "project_id", codec.ID[Project](), changes.fields.ProjectID, policy.ProjectID); err != nil {
		return record.Model[Task, model.ID[Task]]{}, err
	}
	if err = record.Capture(builder, "slug", codec.String[Slug](), changes.fields.Slug, policy.Slug); err != nil {
		return record.Model[Task, model.ID[Task]]{}, err
	}
	return builder.Build()
}

// TaskAuditFieldSet contains typed historical fields. An omitted field differs from an absent model or SQL NULL.
type TaskAuditFieldSet struct {
	_ [0]*Task
	// ID retains stored tasks.id after write mutators; read accessors do not replace audit values.
	ID foundryvalue.Optional[record.FieldChange[model.ID[Task]]]
	// ProjectID retains stored tasks.project_id after write mutators; read accessors do not replace audit values.
	ProjectID foundryvalue.Optional[record.FieldChange[model.ID[Project]]]
	// Slug retains stored tasks.slug after write mutators; read accessors do not replace audit values.
	Slug foundryvalue.Optional[record.FieldChange[Slug]]
}

// TaskAuditFields reads model-owned history through its declared codecs, without populating a partial model.
// Get on a redacted field reports an explicit error; its Snapshot remains available for deliberate audit export.
func TaskAuditFields(history record.Model[Task, model.ID[Task]]) (TaskAuditFieldSet, error) {
	view, err := record.Inspect(history)
	if err != nil {
		return TaskAuditFieldSet{}, err
	}
	var fields TaskAuditFieldSet
	fields.ID, err = record.ReadField(view, "id", codec.ID[Task]())
	if err != nil {
		return TaskAuditFieldSet{}, err
	}
	fields.ProjectID, err = record.ReadField(view, "project_id", codec.ID[Project]())
	if err != nil {
		return TaskAuditFieldSet{}, err
	}
	fields.Slug, err = record.ReadField(view, "slug", codec.String[Slug]())
	if err != nil {
		return TaskAuditFieldSet{}, err
	}
	return fields, nil
}

// TaskAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func TaskAuditing(policy TaskAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Task]()
		if err != nil {
			return err
		}
		return RegisterTaskObserver(registrar, pool, NewTaskObserver(name), func(resolver foundation.Resolver) (func() TaskHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() TaskHooks {
				write := func(ctx context.Context, tx *database.Tx, changes TaskChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return TaskHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
